#!/bin/bash
# Install the optimized midilink and mt32d on MiSTer.
# The binaries are embedded in this script (base64, below main()).
#
# usage: midilink_mt32d_install.sh
#
# - The current /usr/sbin/midilink and /usr/sbin/mt32d are backed up first to
#   /media/fat/linux/backup_midilink_<date-time>/. A file that already is this
#   version is not backed up, so re-running does not pile up useless backups.
# - Undo with midilink_mt32d_restore.sh (only midilink and mt32d; a file that
#   did not exist before installing cannot be removed by it).
# - Run with: bash midilink_mt32d_install.sh
# - Running midilink/mt32d processes are not touched; re-select the UART MIDI
#   mode in the MiSTer menu (or reboot) to start the new binaries.
# - A MiSTer Linux update replaces /usr/sbin, so run this again afterwards.

SBIN=${SBIN:-/usr/sbin}
BACKUP_BASE=${BACKUP_BASE:-/media/fat/linux}
MIDILINK_MD5=92bb9452d088629d9cb7556d4c4c3cee
MT32D_MD5=bb8e888624ceb761af7a7b45683baf48

die() { echo "ERROR: $*" >&2; exit 1; }

main() {
	[ -w "$SBIN" ] || die "$SBIN is not writable (run as root on the MiSTer)"
	for c in base64 md5sum install cmp mktemp; do
		command -v $c >/dev/null || die "missing tool: $c"
	done

	TMP=$(mktemp -d) || die "mktemp failed"
	trap 'rm -rf "$TMP"' EXIT

	# 1. unpack and verify the embedded binaries
	payload_midilink > "$TMP/midilink" || die "unpacking midilink failed"
	payload_mt32d    > "$TMP/mt32d"    || die "unpacking mt32d failed"
	local f want got
	for f in midilink mt32d; do
		[ "$f" = midilink ] && want=$MIDILINK_MD5 || want=$MT32D_MD5
		got=$(md5sum "$TMP/$f" | cut -c1-32)
		[ "$got" = "$want" ] || die "$f: embedded data is corrupt (md5 $got, expected $want)"
	done

	# 2. back up whatever is installed now, unless it already is this version
	# MiSTer has no RTC: an unset clock gives a backup dir that sorts as older
	# than earlier ones, so "restore newest" would pick the wrong one.
	[ "$(date +%Y)" -ge 2025 ] \
		|| echo "WARNING: system clock is not set ($(date +%Y-%m-%d)); check backup dir names before restoring"
	local backup=$BACKUP_BASE/backup_midilink_$(date +%Y%m%d-%H%M%S)
	for f in midilink mt32d; do
		[ -f "$SBIN/$f" ] || continue
		if cmp -s "$SBIN/$f" "$TMP/$f"; then
			echo "  $f: already this version, no backup needed"
			continue
		fi
		mkdir -p "$backup" || die "cannot create $backup"
		# plain cp: /media/fat is exFAT, where cp -p can fail on chmod
		cp "$SBIN/$f" "$backup/$f" && cmp -s "$SBIN/$f" "$backup/$f" \
			|| die "backup of $f failed - nothing was changed"
		echo "  $f: backed up to $backup"
	done

	# 3. install (install writes a new inode, so running processes are unaffected)
	for f in midilink mt32d; do
		install -m 755 "$TMP/$f" "$SBIN/$f" \
			|| die "installing $f failed - run midilink_mt32d_restore.sh to roll back"
		cmp -s "$TMP/$f" "$SBIN/$f" \
			|| die "$f: verification failed after copy - run midilink_mt32d_restore.sh to roll back"
		echo "  $f: installed ($(md5sum "$SBIN/$f" | cut -c1-32))"
	done
	sync

	echo "Done. Re-select the UART MIDI mode in the MiSTer menu (or reboot) to use the new files."
}

